-- Runs the assembled addon entry (generated by scripts/build.py) in a test VM with a stand-in loader: outside the
-- game the real module lookup finds no game.dll, so the addon disables itself without hooking anything and says
-- why in its log. Usage: luajit tests/test_entry.lua <path to the assembled entry>
local path = assert(arg[1], 'entry path required')
local lines = {}
_G.CowboyBingusModLoader = {api = 1, jit = {}, open_log = function()
    return {write = function(_, text) lines[#lines + 1] = text end, flush = function() end}
end}
local function vanilla() return 'vanilla' end
_G.update, _G.shutdown = vanilla, nil
local quiet = print
print = function() end -- the addon's console line
local chunk = assert(loadfile(path))
chunk()
print = quiet
assert(_G.update == vanilla and _G.shutdown == nil, 'a refused copy hooked the game')
assert(rawget(_G, 'HolsterYourShieldInstalled') == nil, 'a refused copy marked itself installed')
assert(#lines == 1 and lines[1]:find('^Disabled: game modules unavailable'), table.concat(lines, ' | '))
-- A copy that finds the flag set (a second deployed copy after a successful install) returns at once.
rawset(_G, 'HolsterYourShieldInstalled', true)
chunk()
assert(#lines == 1 and _G.update == vanilla, 'a second copy did something')
print('PASS: assembled entry refuses outside the game and steps aside for an installed copy')
